import hmac
import hashlib

def verify_signature(secret: str, payload_bytes: bytes, expected_sig: str) -> bool:
    computed = hmac.new(secret.encode("utf-8"), payload_bytes, hashlib.sha256).hexdigest()
    return hmac.compare_digest(computed, expected_sig)

