import json
from signature import verify_signature
from dedup_store import IdempotencyStore

class WebhookHandler:
    def __init__(self, secret: str, store: IdempotencyStore):
        self.secret = secret
        self.store = store
        self.processed_count = 0

    def process_webhook(self, event_id: str, payload_json: str, signature: str) -> dict:
        # Bug: checks idempotency store before verifying signature
        cached = self.store.get(event_id)
        if cached is not None:
            return cached

        # Signature verification
        valid = verify_signature(self.secret, payload_json.encode("utf-8"), signature)
        if not valid:
            return {"status": 401, "error": "Invalid signature"}

        self.processed_count += 1
        result = {"status": 200, "event_id": event_id, "result": "processed"}
        self.store.save(event_id, result)
        return result

